vint8mf8_t __riscv_vssrl_vv_i8mf8(vint8mf8_t vs2, vuint8mf8_t vs1, size_t vl);
vuint8mf8_t __riscv_vssrl_vv_u8mf8(vuint8mf8_t vs2, vuint8mf8_t vs1, size_t vl);
// ... (all SEW/LMUL combinations; signed and unsigned variants)

// vssrl.vx
vint8mf8_t __riscv_vssrl_vx_i8mf8(vint8mf8_t vs2, size_t rs1, size_t vl);
vuint8mf8_t __riscv_vssrl_vx_u8mf8(vuint8mf8_t vs2, size_t rs1, size_t vl);

// vssrl.vi
vint8mf8_t __riscv_vssrl_vi_i8mf8(vint8mf8_t vs2, size_t uimm, size_t vl);
vuint8mf8_t __riscv_vssrl_vi_u8mf8(vuint8mf8_t vs2, size_t uimm, size_t vl);
```

The `vxrm` rounding mode is implicitly read; there are no intrinsics that pass `vxrm` as an explicit argument—it's set via the `vxrm` CSR.

