vuint8mf8_t __riscv_vnclipu_wi_u8mf8(vuint16mf4_t vs2, uint8_t uimm, unsigned int vxrm, size_t vl);

// Signed narrowing clip
vint8mf8_t __riscv_vnclip_wv_i8mf8(vint16mf4_t vs2, vuint8mf8_t vs1, unsigned int vxrm, size_t vl);
