vfloat32m1_t __riscv_vfwmsac_vv_f32m1(vfloat32m1_t vd, vfloat16m1_t vs1, vfloat16m1_t vs2, size_t vl);
vfloat32m1_t __riscv_vfwmsac_vf_f32m1(vfloat32m1_t vd, float16_t rs1, vfloat16m1_t vs2, size_t vl);

// vfwnmsac
vfloat32m1_t __riscv_vfwnmsac_vv_f32m1(vfloat32m1_t vd, vfloat16m1_t vs1, vfloat16m1_t vs2, size_t vl);
vfloat32m1_t __riscv_vfwnmsac_vf_f32m1(vfloat32m1_t vd, float16_t rs1, vfloat16m1_t vs2, size_t vl);
```

(Examples shown for SEW=16, LMUL=1; other type suffixes follow standard RVV naming.)

