vbool1_t __riscv_vmfeq_vv_f32mf2_b64(vfloat32mf2_t vs2, vfloat32mf2_t vs1, size_t vl);
vbool1_t __riscv_vmfeq_vf_f32mf2_b64(vfloat32mf2_t vs2, float rs1, size_t vl);
vbool1_t __riscv_vmfeq_vv_f64m1_b64(vfloat64m1_t vs2, vfloat64m1_t vs1, size_t vl);
vbool1_t __riscv_vmfeq_vf_f64m1_b64(vfloat64m1_t vs2, double rs1, size_t vl);

// vmfne
vbool1_t __riscv_vmfne_vv_f16mf4_b64(vfloat16mf4_t vs2, vfloat16mf4_t vs1, size_t vl);
vbool1_t __riscv_vmfne_vf_f16mf4_b64(vfloat16mf4_t vs2, _Float16 rs1, size_t vl);
vbool1_t __riscv_vmfne_vv_f32mf2_b64(vfloat32mf2_t vs2, vfloat32mf2_t vs1, size_t vl);
vbool1_t __riscv_vmfne_vf_f32mf2_b64(vfloat32mf2_t vs2, float rs1, size_t vl);
vbool1_t __riscv_vmfne_vv_f64m1_b64(vfloat64m1_t vs2, vfloat64m1_t vs1, size_t vl);
